/**
 * @description Tests for the IH_SamplePayloadBuilder template: one body per record, none for an empty request.
 */
@IsTest
private class IH_SamplePayloadBuilderTest {

    private static final String USER_DOMAIN = '@ihsamplepayload.example.com';

    @TestSetup
    static void setup() {
        List<Profile> profiles = [SELECT Id FROM Profile WHERE Name = 'Standard User' WITH SYSTEM_MODE LIMIT 1];
        Id profileId = profiles.isEmpty() ? UserInfo.getProfileId() : profiles[0].Id;
        String unique = EncodingUtil.convertToHex(Crypto.generateAesKey(128)).left(10);
        User tester = new User(LastName = 'IH Sample Tester', Alias = unique.left(8), Email = unique + '@example.com',
            Username = unique + '.payload' + USER_DOMAIN, ProfileId = profileId, EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US', LocaleSidKey = 'en_US', TimeZoneSidKey = 'America/Chicago');
        System.runAs(new User(Id = UserInfo.getUserId())) {
            insert tester;
        }
    }

    private static User tester() {
        String pattern = '%.payload' + USER_DOMAIN;
        return [SELECT Id FROM User WHERE Username LIKE :pattern WITH SYSTEM_MODE LIMIT 1];
    }

    @IsTest
    static void buildsOneBodyPerRecord() {
        List<Id> recordIds = new List<Id>();
        System.runAs(new User(Id = UserInfo.getUserId())) {
            try {
                Case c = new Case(Subject = 'Sample payload test');
                insert c;
                recordIds.add(c.Id);
            } catch (DmlException e) {
                recordIds.clear();
            }
        }
        System.runAs(tester()) {
            IntegrationHub.PayloadRequest req = new IntegrationHub.PayloadRequest();
            req.recordIds = recordIds;
            Map<Id, Object> bodies = new IH_SamplePayloadBuilder().build(req);
            Assert.areEqual(recordIds.size(), bodies.size(), 'one body per record');
            Assert.isTrue(new IH_SamplePayloadBuilder().build(null).isEmpty(), 'no request gives no bodies');
            Assert.isTrue(new IH_SamplePayloadBuilder().build(new IntegrationHub.PayloadRequest()).isEmpty(), 'no Ids give no bodies');
        }
    }

    @IsTest
    static void bodyMapsTheFields() {
        System.runAs(tester()) {
            Map<String, Object> body = IH_SamplePayloadBuilder.body(new Case(Subject = 'S', Status = 'New'));
            Assert.areEqual('S', body.get('title'), 'the subject is sent as title');
            Assert.areEqual('New', body.get('status'), 'the status is sent');
            Assert.isTrue(body.containsKey('customer'), 'the customer block is sent');
        }
    }
}
